class TicTacToe:
    def __init__(self, n: int):
        self.n = n
        self.rows = [0] * n
        self.cols = [0] * n
        self.diag = 0        # cells where row == col
        self.anti = 0        # cells where row + col == n - 1

    def move(self, row: int, col: int, player: int) -> int:
        delta = 1 if player == 1 else -1
        self.rows[row] += delta
        self.cols[col] += delta
        if row == col:
            self.diag += delta
        if row + col == self.n - 1:
            self.anti += delta
        target = self.n * delta
        if target in (self.rows[row], self.cols[col], self.diag, self.anti):
            return player
        return 0

