class _Bucket:
    __slots__ = ("count", "keys", "prev", "next")

    def __init__(self, count=0):
        self.count = count
        self.keys = set()
        self.prev = self.next = None


class AllOne:
    def __init__(self):
        self.head, self.tail = _Bucket(), _Bucket()   # sentinels, counts ascend toward tail
        self.head.next, self.tail.prev = self.tail, self.head
        self.where = {}                               # key -> bucket holding it

    def _insert_after(self, node, count):
        bucket = _Bucket(count)
        bucket.prev, bucket.next = node, node.next
        node.next.prev = bucket
        node.next = bucket
        return bucket

    def _remove_if_empty(self, bucket):
        if not bucket.keys:
            bucket.prev.next, bucket.next.prev = bucket.next, bucket.prev

    def inc(self, key: str) -> None:
        cur = self.where.get(key, self.head)
        nxt = cur.next
        if nxt is self.tail or nxt.count != cur.count + 1:
            nxt = self._insert_after(cur, cur.count + 1)
        nxt.keys.add(key)
        self.where[key] = nxt
        if cur is not self.head:
            cur.keys.discard(key)
            self._remove_if_empty(cur)

    def dec(self, key: str) -> None:
        cur = self.where[key]
        if cur.count == 1:
            del self.where[key]
        else:
            prv = cur.prev
            if prv is self.head or prv.count != cur.count - 1:
                prv = self._insert_after(prv, cur.count - 1)
            prv.keys.add(key)
            self.where[key] = prv
        cur.keys.discard(key)
        self._remove_if_empty(cur)

    def getMaxKey(self) -> str:
        last = self.tail.prev
        return next(iter(last.keys)) if last is not self.head else ""

    def getMinKey(self) -> str:
        first = self.head.next
        return next(iter(first.keys)) if first is not self.tail else ""

