def plus_one(digits: list[int]) -> list[int]:
    result = digits[:]
    for i in range(len(result) - 1, -1, -1):
        if result[i] < 9:
            result[i] += 1     # no further carry
            return result
        result[i] = 0          # 9 rolls over; carry continues left
    return [1] + result        # all digits were 9

