def backspace_compare(s: str, t: str) -> bool:
    def next_kept(text: str, i: int) -> int:
        # Move left from i to the index of the next character that survives.
        skip = 0
        while i >= 0:
            if text[i] == "#":
                skip += 1
            elif skip:
                skip -= 1
            else:
                break
            i -= 1
        return i

    i, j = len(s) - 1, len(t) - 1
    while True:
        i, j = next_kept(s, i), next_kept(t, j)
        if i < 0 or j < 0:
            return i < 0 and j < 0
        if s[i] != t[j]:
            return False
        i -= 1
        j -= 1

