def remove_occurrences(s: str, part: str) -> str:
    m = len(part)
    # KMP failure table: fail[k] = length of the longest proper border of part[:k + 1].
    fail = [0] * m
    k = 0
    for i in range(1, m):
        while k and part[i] != part[k]:
            k = fail[k - 1]
        if part[i] == part[k]:
            k += 1
        fail[i] = k

    chars = []      # surviving characters
    matched = [0]   # matched[i] = KMP state after the first i surviving characters
    for ch in s:
        k = matched[-1]
        while k and ch != part[k]:
            k = fail[k - 1]
        if ch == part[k]:
            k += 1
        chars.append(ch)
        matched.append(k)
        if k == m:
            # The stack ends with part: drop it, restoring the earlier state.
            del chars[-m:]
            del matched[-m:]
    return "".join(chars)

