def get_results(queries: list[list[int]]) -> list[bool]:
    limit = max(q[1] for q in queries) + 1
    placed = sorted(q[1] for q in queries if q[0] == 1)

    # Doubly linked list over the final obstacle set, with 0 as a wall.
    prev = [0] * (limit + 1)
    nxt = [-1] * (limit + 1)
    chain = [0] + placed
    for a, b in zip(chain, chain[1:]):
        nxt[a] = b
        prev[b] = a

    # Fenwick tree for prefix maxima of "gap ending at this obstacle".
    tree = [0] * (limit + 1)

    def raise_to(i, v):
        while i <= limit:
            if tree[i] < v:
                tree[i] = v
            i += i & -i

    def prefix_max(i):
        best = 0
        while i > 0:
            if tree[i] > best:
                best = tree[i]
            i -= i & -i
        return best

    for p in placed:
        raise_to(p, p - prev[p])

    # Union find: parent[i] == i only for live obstacles and the wall at 0.
    parent = list(range(limit + 1))
    is_obstacle = [False] * (limit + 1)
    for p in placed:
        is_obstacle[p] = True
    for i in range(1, limit + 1):
        if not is_obstacle[i]:
            parent[i] = i - 1

    def find(i):
        root = i
        while parent[root] != root:
            root = parent[root]
        while parent[i] != root:
            parent[i], i = root, parent[i]
        return root

    answers = []
    for q in reversed(queries):
        if q[0] == 1:
            x = q[1]
            before, after = prev[x], nxt[x]
            nxt[before] = after
            if after != -1:
                prev[after] = before
                raise_to(after, after - before)  # the two gaps merge
            parent[x] = x - 1
        else:
            x, size = q[1], q[2]
            room = max(prefix_max(x), x - find(x))
            answers.append(room >= size)
    answers.reverse()
    return answers

