def valid_ip_address(queryIP: str) -> str:
    digits = set("0123456789")
    hexdigits = set("0123456789abcdefABCDEF")

    def is_v4(parts):
        if len(parts) != 4:
            return False
        for p in parts:
            if not 1 <= len(p) <= 3 or any(c not in digits for c in p):
                return False
            if p[0] == "0" and len(p) > 1:
                return False      # leading zero
            if int(p) > 255:
                return False
        return True

    def is_v6(parts):
        if len(parts) != 8:
            return False
        return all(1 <= len(p) <= 4 and all(c in hexdigits for c in p) for p in parts)

    if "." in queryIP and is_v4(queryIP.split(".")):
        return "IPv4"
    if ":" in queryIP and is_v6(queryIP.split(":")):
        return "IPv6"
    return "Neither"

