class MaxStack:
    def __init__(self):
        self.stack = []        # (id, value) in push order
        self.heap = []         # (-value, -id): largest value, then newest first
        self.removed = set()   # ids removed through the other structure
        self.next_id = 0

    def push(self, x: int) -> None:
        self.stack.append((self.next_id, x))
        heapq.heappush(self.heap, (-x, -self.next_id))
        self.next_id += 1

    def _clean_stack(self):
        while self.stack[-1][0] in self.removed:
            self.removed.discard(self.stack.pop()[0])

    def _clean_heap(self):
        while -self.heap[0][1] in self.removed:
            self.removed.discard(-heapq.heappop(self.heap)[1])

    def pop(self) -> int:
        self._clean_stack()
        uid, x = self.stack.pop()
        self.removed.add(uid)      # its heap entry is now stale
        return x

    def top(self) -> int:
        self._clean_stack()
        return self.stack[-1][1]

    def peekMax(self) -> int:
        self._clean_heap()
        return -self.heap[0][0]

    def popMax(self) -> int:
        self._clean_heap()
        neg_x, neg_id = heapq.heappop(self.heap)
        self.removed.add(-neg_id)  # its stack entry is now stale
        return -neg_x

