def rob(root: Optional[TreeNode]) -> int:
    if root is None:
        return 0
    # Preorder via a stack; reversing it puts children before parents.
    order, stack = [], [root]
    while stack:
        node = stack.pop()
        order.append(node)
        if node.left:
            stack.append(node.left)
        if node.right:
            stack.append(node.right)

    best = {None: (0, 0)}   # node -> (take, skip)
    for node in reversed(order):
        lt, ls = best[node.left]
        rt, rs = best[node.right]
        take = node.val + ls + rs
        skip = max(lt, ls) + max(rt, rs)
        best[node] = (take, skip)
    return max(best[root])

