    def __init__(self, sentences: list[str], times: list[int]):
        self.root = self._new_node()
        for sentence, count in zip(sentences, times):
            self._record(sentence, count)
        self.buffer = []
        self.node = self.root    # None once the typed prefix matches nothing

    @staticmethod
    def _new_node():
        return {"kids": {}, "hot": {}}

    def _record(self, sentence: str, count: int) -> None:
        # Add count to sentence at every node along its path.
        node = self.root
        for ch in sentence:
            node = node["kids"].setdefault(ch, self._new_node())
            node["hot"][sentence] = node["hot"].get(sentence, 0) + count

    def input(self, c: str) -> list[str]:
        if c == "#":
            self._record("".join(self.buffer), 1)
            self.buffer = []
            self.node = self.root
            return []
        self.buffer.append(c)
        if self.node is not None:
            self.node = self.node["kids"].get(c)
        if self.node is None:
            return []
        best = heapq.nsmallest(3, self.node["hot"].items(), key=lambda kv: (-kv[1], kv[0]))
        return [sentence for sentence, _ in best]

